class Solution {
  public int maxSubstrings(String word) {
    int[] first = new int[26];
    java.util.Arrays.fill(first, -1);
    int count = 0;
    for (int i = 0; i < word.length(); i++) {
      int c = word.charAt(i) - 'a';
      if (first[c] >= 0 && i - first[c] >= 3) {
        count++;
        java.util.Arrays.fill(first, -1);
      } else if (first[c] < 0) {
        first[c] = i;
      }
    }
    return count;
  }
}
